"""Return sensitivity

    counts: dict of counts, containing at least TP and FN
    """
def sensitivity_formula(counts: Any) -> object {
    tp = counts['TP'];
    fn = counts['FN'];
    if (not tp and not fn) {
        return 0.0;
    }
    sensitivity = tp / (tp + fn);
    return sensitivity;
}

