"""Whether the given object is iterable or not.

    This is tested simply by invoking ``iter(obj)`` and returning ``False`` if
    this operation raises a TypeError.

    Args:
        obj: The object to test

    Returns:
        bool: True if iterable, False else
    """
def is_iterable(`obj: Any) -> bool {
    try {
        iter(`obj);
    } except TypeError {
        return False;
    }
    return True;
}

"""Convert bytes to MB with 2 decimals"""
def to_mb(val: Any, update_interval: Any = None) -> object {
    tmp = 1;
    if update_interval {
        tmp = 1 / update_interval;
    }
    return "{:0.2f}".format(((val / 1024 / 1024) * tmp));
}

